// Groth16 proving for the gatekeeper circuit (snarkjs, BN128).
// Circuit: GatekeeperEvaluation, 13 public inputs, 0 private inputs.
// Artifacts: gatekeeper.wasm (1.7 MB) + gatekeeper_final.zkey (0.3 MB).
// The zkey stays embedded as base64 (src/zkey-b64.js, generated by
// tools/build-assets.mjs). The circuit wasm is loaded as a STATIC WebAssembly
// MODULE (src/gatekeeper.wasm, copied from ../circuits/) — see below.
//
// WHY TWO PATHS — Cloudflare Workers bans WebAssembly.compile() at runtime
// ("Wasm code generation disallowed by embedder"), which snarkjs calls in
// two places:
//   1. circom_runtime's witness calculator (WebAssembly.compile of the
//      circuit wasm). FIX: instantiate a statically-imported Module and hand
//      the Instance to WitnessCalculatorBuilder — it accepts an Instance
//      directly, no compile. Verified in workerd: witness in ~90 ms.
//   2. ffjavascript's BN128 curve engine: the engine wasm is GENERATED at
//      runtime by wasmbuilder (ModuleBuilder.build()) and then compiled in
//      buildThreadManager. FIX: the generated bytes are DETERMINISTIC
//      (byte-identical across runs, sha256 eea61e66…8639, and identical to
//      wasmcurves/build/bn128.wasm), so a prebuilt Module is injected via
//      globalThis.__BN128_WASM_MODULE__ (see ffjavascript patches in
//      ../patches/) and buildThreadManager instantiates it instead of
//      compiling. Verified in workerd: full prove+verify in ~600 ms total,
//      inside the 60 s response deadline.
// Node fallback: Node cannot link a .wasm whose imports ("env"/"runtime")
// are not ESM packages, so the dynamic imports below throw in Node and the
// prover falls back to the original snarkjs fullProve with embedded bytes
// (WebAssembly.compile is allowed in Node). `npm test` exercises this path.
//
// OPEN (OQ3): the platform never publishes how registeredVkHash / proofVkHash
// (32-byte hashes), salt, and taskId (string) map to field elements. The
// mappings below are the natural deterministic choices:
//   vkHash  -> BigInt(0xhash) mod p
//   taskId  -> UUID part as a 128-bit integer (sha256 mod p only as a
//              fallback for non-UUID ids) — changed 19 Nov 2026 per the
//              taskId-mapping fix (fellow participant's Round 3 evidence);
//              previously BigInt(sha256(taskId)) mod p, which failed
//              platform verification
//   salt    -> BigInt(sha256("salt:" + taskId)) mod p  (deterministic per task,
//              so retries of the same task_id prove identically)
// If practice mode shows the platform recomputes these differently, change
// the three mapping functions — the rest of the flow is unaffected.

import * as snarkjs from "snarkjs";
import { WitnessCalculatorBuilder } from "circom_runtime";
import * as fastFile from "fastfile";
import { Scalar } from "ffjavascript";
import { WASM_B64 } from "./wasm-b64.js";
import { ZKEY_B64 } from "./zkey-b64.js";

// BN128 scalar field prime.
const FIELD_P = 21888242871839275222246405745257275088548364400416034343698204186575808495617n;

// Decision encoding — probe T1/T2 (circuit-probe.js) confirms 1 = checks pass
// (APPROVE), 0 = REJECT. If the probe says otherwise, flip these two lines.
export const DECISION_APPROVE = "1";
export const DECISION_REJECT = "0";

// Offsets of the prebuilt BN128 engine wasm (wasmcurves/build/bn128.wasm,
// deterministic ModuleBuilder output). q/r are the BN128 field/modulus.
const BN128_META = {
  pq: 488, pr: 1768,
  pG1gen: 31432, pG1zero: 31528, pG1b: 3080,
  pG2gen: 31624, pG2zero: 31816, pG2b: 12456,
  pOneT: 32008, prePSize: 192, preQSize: 19776,
  q: "21888242871839275222246405745257275088696311157297823662689037894645226208583",
  r: "21888242871839275222246405745257275088548364400416034343698204186575808495617",
};

let wasmBytes = null;
let zkeyBytes = null;

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function getArtifacts() {
  if (!wasmBytes) wasmBytes = b64ToBytes(WASM_B64);
  if (!zkeyBytes) zkeyBytes = b64ToBytes(ZKEY_B64);
  return { wasmBytes, zkeyBytes };
}

// Statically-bundled wasm Modules (compiled at deploy time by wrangler /
// esbuild — no runtime WebAssembly.compile). Dynamic import so Node, which
// cannot link these modules, throws here and the caller falls back to the
// embedded-bytes path below.
let wasmModulesCache = null;
async function loadWasmModules() {
  if (wasmModulesCache) return wasmModulesCache;
  let gatekeeper = null;
  let bn128 = null;
  try {
    gatekeeper = (await import("./gatekeeper.wasm")).default;
  } catch {
    gatekeeper = null;
  }
  try {
    bn128 = (await import("./bn128-engine.wasm")).default;
  } catch {
    bn128 = null;
  }
  wasmModulesCache = { gatekeeper, bn128 };
  return wasmModulesCache;
}

async function sha256Hex(text) {
  const data = new TextEncoder().encode(text);
  const digest = await crypto.subtle.digest("SHA-256", data);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// 32-byte hash -> field element: integer value mod p.
function hashToField(hex) {
  const clean = String(hex).trim().toLowerCase().replace(/^0x/, "");
  return (BigInt("0x" + clean) % FIELD_P).toString();
}

// String id -> field element: sha256(id) mod p.
async function stringToField(text) {
  const h = await sha256Hex(text);
  return (BigInt("0x" + h) % FIELD_P).toString();
}

// Task id -> field element: the identifier part (UUID) as a 128-bit
// integer; SHA-256 mod p only as a fallback for non-UUID ids.
// Rationale: fellow participant's Round 3 evidence (see
// taskid-mapping-fix-DRAFT.md) — hashing the whole "prefix_uuid" string
// fails platform verification, while the UUID-as-integer verifies.
// Prefix-independent: "practice_<uuid>" and "task_<uuid>" map identically.
async function taskIdToField(taskId) {
  const m = String(taskId).match(
    /([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})/,
  );
  if (m) return (BigInt("0x" + m[1].replace(/-/g, "")) % FIELD_P).toString();
  return stringToField(taskId);
}

// 160-bit address -> field element: integer value (fits in the field).
function addressToField(hex) {
  const clean = String(hex).trim().toLowerCase().replace(/^0x/, "");
  return BigInt("0x" + clean).toString();
}

/**
 * Build the 13 circuit inputs from a task envelope + decision.
 * Input names are the bare signal names (no `main.` prefix).
 */
export async function buildCircuitInput(task, decision) {
  const input = task.input;
  return {
    minimum: String(input.minimum),
    recipient: addressToField(input.recipient),
    amount: String(input.amount),
    publicBalance: String(input.public_balance),
    expiryBlock: String(input.expiry_block),
    currentBlock: String(input.current_block),
    conditionRecipient: addressToField(input.condition_recipient),
    maxTransfer: String(input.max_transfer),
    registeredVkHash: hashToField(input.registered_vk),
    proofVkHash: hashToField(input.proof_vk),
    salt: await stringToField("salt:" + task.task_id),
    decision: decision === "APPROVE" ? DECISION_APPROVE : DECISION_REJECT,
    taskId: await taskIdToField(task.task_id),
  };
}

// Instantiate the statically-imported circuit Module with the imports the
// circom wasm expects (mirrors circom_runtime's builder imports; only the
// error/log helpers are used by this circuit — the rest are present because
// the module requires all of them at instantiation).
async function instantiateCircuit(gatekeeperModule) {
  let instance = null;
  let wc = null;
  let errStr = "";
  let msgStr = "";
  // Workers memory limit: the isolate caps at 128 MiB, so the circom_runtime
  // default of 32767 pages (2 GiB) FAILS in production with
  // "WebAssembly.Memory(): could not allocate memory" (local workerd does
  // not enforce the limit, which is why the 32767 version passed local
  // verification). This circuit is tiny (nVars=647, nPublic=13, wasm min
  // 27 pages) — 256 pages (16 MiB) is >4x headroom for witness + buffers.
  const memory = new WebAssembly.Memory({ initial: 256 });
  function getMessage() {
    let m = "";
    let c = instance.exports.getMessageChar();
    while (c !== 0) {
      m += String.fromCharCode(c);
      c = instance.exports.getMessageChar();
    }
    return m;
  }
  function p2str(p) {
    const i8 = new Uint8Array(memory.buffer);
    const bytes = [];
    for (let i = 0; i8[p + i] > 0; i++) bytes.push(i8[p + i]);
    return String.fromCharCode.apply(null, bytes);
  }
  instance = await WebAssembly.instantiate(gatekeeperModule, {
    env: { memory },
    runtime: {
      printDebug: (v) => console.log("printDebug:", v),
      exceptionHandler: (code) => {
        throw new Error("circom exception " + code + " " + errStr);
      },
      printErrorMessage: () => {
        errStr += getMessage() + "\n";
      },
      writeBufferMessage: () => {
        const msg = getMessage();
        if (msg === "\n") {
          console.log(msgStr);
          msgStr = "";
        } else {
          msgStr += (msgStr !== "" ? " " : "") + msg;
        }
      },
      showSharedRWMemory: () => {
        const n = instance.exports.getFieldNumLen32();
        const arr = new Uint32Array(n);
        for (let j = 0; j < n; j++) arr[n - 1 - j] = instance.exports.readSharedRWMemory(j);
        console.log(Scalar.fromArray(arr, 0x100000000).toString());
      },
      error: (code, pstr, a, b, c, d) => {
        const msg =
          p2str(pstr) + " " + wc.getFr(b).toString() + " != " + wc.getFr(c).toString() + " " + p2str(d);
        console.log("ERROR:", code, msg);
        throw new Error(msg);
      },
      log: (a) => console.log(wc.getFr(a).toString()),
      logGetSignal: () => {},
      logSetSignal: () => {},
      logStartComponent: () => {},
      logFinishComponent: () => {},
    },
  });
  return instance;
}

/**
 * Generate a Groth16 proof for a task + decision.
 * Returns { proof, publicSignals } (snarkjs shapes), or throws.
 * The proof is verified locally before it is returned — a proof that fails
 * local verification is never sent.
 *
 * Workers path (static Modules available): witness via the pre-instantiated
 * circuit + snarkjs groth16.prove with the prebuilt BN128 engine, single
 * thread (no Web Worker API in Workers). Node path: original fullProve with
 * embedded bytes.
 */
export async function proveDecision(task, decision, vk) {
  const circuitInput = await buildCircuitInput(task, decision);
  const mods = await loadWasmModules();
  const { zkeyBytes } = getArtifacts();

  if (mods.gatekeeper instanceof WebAssembly.Module) {
    if (mods.bn128 instanceof WebAssembly.Module) {
      globalThis.__BN128_WASM_MODULE__ = { module: mods.bn128, meta: BN128_META };
    }
    const instance = await instantiateCircuit(mods.gatekeeper);
    const wc = await WitnessCalculatorBuilder(instance);
    const wtnsBytes = await wc.calculateWTNSBin(circuitInput);
    const wtnsFile = { type: "mem" };
    const fd = await fastFile.createOverride(wtnsFile);
    await fd.write(wtnsBytes);
    await fd.close();
    const { proof, publicSignals } = await snarkjs.groth16.prove(
      zkeyBytes,
      wtnsFile,
      undefined,
      { singleThread: true },
    );
    if (vk) {
      const ok = await snarkjs.groth16.verify(vk, publicSignals, proof);
      if (!ok) throw new Error("local proof verification failed");
    }
    return { proof, publicSignals };
  }

  // Node / dev fallback — WebAssembly.compile is allowed here.
  const { wasmBytes } = getArtifacts();
  const { proof, publicSignals } = await snarkjs.groth16.fullProve(
    circuitInput,
    wasmBytes,
    zkeyBytes,
  );
  if (vk) {
    const ok = await snarkjs.groth16.verify(vk, publicSignals, proof);
    if (!ok) throw new Error("local proof verification failed");
  }
  return { proof, publicSignals };
}
